// Simulate the described string transformation and return the final string of length n.
// n: initial length of the string (and final length of output)
// k: number of steps to perform, but the process stops early after n 'B' operations.
// s: initial string consisting of 'A' and 'B'.
std::string processString(int n, int k, const std::string& s) {
    // Store characters as 0 for 'A', 1 for 'B'.
    std::deque<int> d;
    for (char c : s) {
        d.push_back(c == 'B' ? 1 : 0);
    }

    int flip = 0;      // Global flip flag: effective value = stored XOR flip.
    int steps = 0;     // Number of steps actually executed.
    int bOps = 0;      // Number of 'B' operations (removals) performed.

    // The total number of steps never exceeds 2*n (each 'A' flip is followed by a 'B' removal).
    while (steps < k && bOps < n) {
        if ((d.front() ^ flip) == 0) {
            // Effective front is 'A': flip it to 'B' by toggling the stored bit.
            d.front() ^= 1;
        } else {
            // Effective front is 'B': remove it, toggle the global flip,
            // and append an 'A' (stored bit equals the new flip).
            d.pop_front();
            flip ^= 1;
            d.push_back(flip);
            ++bOps;
        }
        ++steps;
    }

    // Build the result from the first n effective characters of the deque.
    std::string result;
    result.reserve(n);
    for (int i = 0; i < n; ++i) {
        result.push_back((d[i] ^ flip) ? 'B' : 'A');
    }
    return result;
}
